<?php
declare(strict_types=1);
namespace Amanah\SEOEngine\Infrastructure\Repository;
use Amanah\SEOEngine\Application\Repository\ContentRequirementRepositoryInterface;
use Amanah\SEOEngine\Domain\ContentIntelligence\ContentRequirement;
defined('ABSPATH') || exit;
final class WordPressContentRequirementRepository extends WordPressRepository implements ContentRequirementRepositoryInterface {
 public function __construct(\wpdb $wpdb){parent::__construct($wpdb,$wpdb->prefix.'amanah_seo_content_requirements');}
 public function findByKey(string $key):?ContentRequirement{$r=$this->wpdb->get_row($this->wpdb->prepare("SELECT * FROM {$this->table} WHERE requirement_key=%s LIMIT 1",$key),ARRAY_A);return $this->hydrate($r);}
 public function findByKeywordId(int $keyword_id,string $status=''):array{$sql="SELECT * FROM {$this->table} WHERE keyword_id=%d";$args=array($keyword_id);if(''!==$status){$sql.=" AND status=%s";$args[]=$status;}$sql.=" ORDER BY priority DESC,id ASC";$rows=$this->wpdb->get_results($this->wpdb->prepare($sql,$args),ARRAY_A);return array_values(array_filter(array_map(array($this,'hydrate'),is_array($rows)?$rows:array())));}
 public function save(ContentRequirement $r):ContentRequirement{$data=array('keyword_id'=>$r->getKeywordId(),'finding_id'=>$r->getFindingId(),'requirement_key'=>$r->getKey(),'requirement_type'=>$r->getType(),'statement'=>$r->getStatement(),'priority'=>$r->getPriority(),'mandatory'=>$r->isMandatory()?1:0,'verification_rule'=>wp_json_encode($r->getVerificationRule()),'status'=>$r->getStatus(),'current_version'=>$r->getVersion(),'updated_at'=>current_time('mysql',true));$f=array('%d','%d','%s','%s','%s','%s','%d','%s','%s','%d','%s');$existing=$this->findByKey($r->getKey());if(null!==$existing){$this->wpdb->update($this->table,$data,array('id'=>$existing->getId()),$f,array('%d'));return new ContentRequirement((int)$existing->getKeywordId(),(int)$existing->getFindingId(),$existing->getKey(),$r->getType(),$r->getStatement(),$r->getPriority(),$r->isMandatory(),$r->getVerificationRule(),$r->getStatus(),$r->getVersion(),$existing->getId());}$data['created_at']=current_time('mysql',true);if(false===$this->wpdb->insert($this->table,$data,$f+array('%s')))throw new \RuntimeException('Content requirement could not be stored.');return new ContentRequirement($r->getKeywordId(),$r->getFindingId(),$r->getKey(),$r->getType(),$r->getStatement(),$r->getPriority(),$r->isMandatory(),$r->getVerificationRule(),$r->getStatus(),$r->getVersion(),(int)$this->wpdb->insert_id);}
 private function hydrate($r):?ContentRequirement{if(!is_array($r))return null;$rule=json_decode((string)$r['verification_rule'],true);return new ContentRequirement((int)$r['keyword_id'],(int)$r['finding_id'],(string)$r['requirement_key'],(string)$r['requirement_type'],(string)$r['statement'],(string)$r['priority'],1===(int)$r['mandatory'],is_array($rule)?$rule:array(),(string)$r['status'],(int)$r['current_version'],(int)$r['id']);}
}